@Override public void onAudioAttributesChanged(int seq,AudioAttributes audioAttributes){
  try {
    @DeviceInfo.PlaybackType int playbackType=sessionImpl.getPlayerWrapper().getDeviceInfo().playbackType;
    if (playbackType == DeviceInfo.PLAYBACK_TYPE_LOCAL) {
      int legacyStreamType=LegacyConversions.getLegacyStreamType(audioAttributes);
      sessionCompat.setPlaybackToLocal(legacyStreamType);
    }
  } catch (NullPointerException | IllegalArgumentException e) {
    e.printStackTrace();
  }
}
